/** 在 ego-browser 已打开的本地合成页面运行；剪贴板只捕获 payload，不接触用户剪贴板。 */
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
export async function runAcceptance(page, artifactDir) {
  const checks=[];
  const check=(name,condition)=>{assert.ok(condition,name);checks.push(name);};
  const settle=()=>page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
  const select=async id=>{await page.selectOption('select[aria-label="Fixture"]',id);await settle();};
  const expand=async()=>{if(await page.evaluate(()=>!document.querySelector('.cx-reader-expanded')))await page.click('.cx-reader-expand');await settle();};
  const shot=async name=>{const size=await page.evaluate(()=>({width:Math.ceil(innerWidth*devicePixelRatio),height:Math.ceil(innerHeight*devicePixelRatio)}));const result=await page.cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:true,clip:{x:0,y:0,...size,scale:1}});await writeFile(`${artifactDir}/${name}.png`,Buffer.from(result.data,'base64'));};
  await mkdir(artifactDir,{recursive:true});
  await page.reload();await page.click('text="English"');
  await page.evaluate(()=>{document.documentElement.dataset.theme='light';Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{window.qaCopied=text;}}});});
  await expand();
  check('Markdown renders headings, table, list, quote and code',await page.evaluate(()=>['.cx-reader-rich h1','.cx-reader-rich table','.cx-reader-rich ul','.cx-reader-rich blockquote','.cx-reader-rich pre code'].every(s=>document.querySelector(s))));
  check('Context wrapper remains visible and is never executed',await page.evaluate(()=>document.querySelector('.cx-reader-literal').textContent.includes('<environment_context>')&&!document.querySelector('.cx-reader script')));
  await page.click('.cx-reader-rich .cx-reader-code-head button');
  check('Fenced code copy is exact without toolbar or line numbers',await page.evaluate(()=>window.qaCopied==='function format(value: string) {\n  return `value: ${value}`;\n}\n'));
  await page.evaluate(()=>{document.querySelector('.cx-reader-table').scrollIntoView({block:'start'});});await shot('01-markdown');
  await page.click('button[aria-label="Close details"]');
  await select('context');await expand();
  await page.click('.cx-reader-heading-toggle >> nth=0');
  const collapsed=await page.evaluate(()=>document.querySelector('.cx-reader-heading-toggle').getAttribute('aria-expanded'));
  await select('json');await select('context');
  check('Section collapse survives closing and switching entries',collapsed==='false'&&await page.evaluate(()=>document.querySelector('.cx-reader-heading-toggle').getAttribute('aria-expanded')==='false'));
  await page.click('.cx-reader-heading-toggle >> nth=0');
  await page.evaluate(()=>{document.querySelector('.cx-detail-body').scrollTop=900;});await settle();
  const scroll=await page.evaluate(()=>document.querySelector('.cx-detail-body').scrollTop);
  await select('json');await select('context');await settle();
  check('Scroll is restored after entry switch',await page.evaluate(expected=>Math.abs(document.querySelector('.cx-detail-body').scrollTop-expected)<3,scroll));
  await page.evaluate(()=>window.readerFixture.refresh());await settle();
  check('Live revision preserves scroll',await page.evaluate(expected=>Math.abs(document.querySelector('.cx-detail-body').scrollTop-expected)<3,scroll));
  await select('json');await expand();
  check('Long value does not hide sibling keys',await page.evaluate(()=>document.querySelector('[aria-label="Expand long_context"]')&&[...document.querySelectorAll('.cx-reader-json-key')].some(e=>e.textContent==='tail')));
  await page.fill('input[placeholder="Search all parsed keys and values…"]','find-me-value');await settle();
  check('JSON search expands the full ancestor path',await page.evaluate(()=>!!document.querySelector('[aria-label="Collapse nested"]')&&!!document.querySelector('[aria-label="Collapse deep"]')&&document.querySelector('.is-match')?.textContent.includes('needle_field')));
  await page.click('[aria-label="Copy value /safe_integer_boundary"]');
  check('Large number copy is lossless',await page.evaluate(()=>window.qaCopied==='900719925474099312345'));
  await page.click('[aria-label="Copy path /nested"]');
  check('Field path copy is JSON Pointer',await page.evaluate(()=>window.qaCopied==='/nested'));
  await page.click('loc=role:button[name="Copy entire JSON body"]');
  check('Whole JSON copy includes collapsed values',await page.evaluate(()=>window.qaCopied.length===32800&&window.qaCopied.includes('1.234567890123456789')));
  await page.evaluate(()=>{document.querySelector('.cx-reader-json').scrollIntoView({block:'start'});});await shot('02-json-search');
  await page.click('[data-reader-part="output"] .cx-reader-collapse');
  check('JSON input and log output render independently',await page.evaluate(()=>!!document.querySelector('[data-reader-part="input"] .cx-reader-json')&&document.querySelector('[data-reader-part="output"] .cx-reader-source').textContent.includes('INFO starting')));
  await page.fill('[aria-label="Search loaded entry body"]','loading assets');await settle();
  await page.click('.cx-reader-search-results button');await settle();
  check('Entry search opens and marks exact body text',await page.evaluate(()=>document.querySelector('[data-reader-hit]').textContent==='loading assets'));
  await select('partial');await expand();
  check('Partial JSON is readable without false format error or field tree',await page.evaluate(()=>!document.querySelector('.cx-reader-json-tree')&&document.querySelector('.cx-reader-notice').textContent.includes('not fully loaded')&&!document.querySelector('.cx-reader').textContent.includes('format error')));
  check('Output not saved is distinct from pagination',await page.evaluate(()=>document.querySelector('[data-reader-part="output"]').textContent.includes('Output not saved')&&document.querySelector('[data-reader-part="input"]').textContent.includes('More content is not loaded')));
  await page.click('[data-reader-part="input"] .cx-more-content >> nth=0');await settle();
  check('Field tree appears only after final body page',await page.evaluate(()=>!!document.querySelector('.cx-reader-json-tree')&&!document.querySelector('.cx-more-content')));
  await select('truncated');await expand();
  check('Truncated source uses honest fallback',await page.evaluate(()=>document.querySelector('.cx-reader').textContent.includes('Source was truncated')&&document.querySelector('.cx-reader').textContent.includes('may be incomplete')&&!document.querySelector('.cx-more-content')));
  await select('command');await expand();
  await page.click('.cx-reader-command .cx-reader-code-head button');
  check('Known command copy preserves indentation and newlines',await page.evaluate(()=>window.qaCopied==="printf 'hello\n'\n  npm test"));
  await page.focus('[aria-label="Field definition /cmd"]');
  check('Definition opens on keyboard focus',await page.evaluate(()=>getComputedStyle(document.querySelector('.cx-reader-help-card')).visibility!=='hidden'&&document.querySelector('.cx-reader-help-card').getBoundingClientRect().height>0));
  await page.click('[aria-label="Field definition /cmd"]');
  check('Pinned definition carries accessible source and reference version',await page.evaluate(()=>document.querySelector('.is-pinned .cx-reader-help-card').textContent.includes('reference only')&&document.querySelector('.is-pinned a').href.startsWith('https://github.com/openai/codex/')));
  await shot('03-tool-definition');
  check('Undefined fields have no invented help',await page.evaluate(()=>!document.querySelector('[aria-label="Field definition /workdir"]')));
  await page.click('loc=role:tab[name="Raw content"]');
  check('Raw retains associated record role',await page.evaluate(()=>document.querySelector('.cx-detail-body').textContent.includes('synthetic_raw_record')));
  await page.click('loc=role:tab[name="Source"]');
  check('Source remains separate',await page.evaluate(()=>document.querySelector('.cx-detail-body').textContent.includes('Synthetic test source')));
  await page.click('loc=role:tab[name="Summary"]');
  check('Summary remains separate',await page.evaluate(()=>document.querySelector('.cx-detail-body').textContent.includes('Entry model tokens')));
  await page.click('loc=role:tab[name="Preview"]');
  await select('error');await expand();
  check('Failure exposes error first',await page.evaluate(()=>document.querySelector('.cx-reader-block').dataset.readerPart==='error'&&document.querySelector('[data-reader-part="error"] .cx-reader-source').textContent.includes('permission denied')));
  await select('unknown');await expand();
  check('Unknown tools retain text and do not execute scripts',await page.evaluate(()=>document.querySelector('.cx-reader-source').textContent.includes('<script>')&&!document.querySelector('.cx-reader script')));
  await page.selectOption('[aria-label="Input format"]','code');
  await page.selectOption('[aria-label="Input code language"]','bash');
  await select('command');await select('unknown');
  check('Manual format and language survive switching',await page.evaluate(()=>document.querySelector('[aria-label="Input format"]').value==='code'&&document.querySelector('[aria-label="Input code language"]').value==='bash'));
  await select('large');await expand();
  const start=Date.now();await page.fill('input[placeholder="Search all parsed keys and values…"]','row-19999');await settle();
  check('Large array search locates last row with bounded DOM',await page.evaluate(()=>document.querySelector('.is-match')?.textContent.includes('row-19999')&&document.querySelectorAll('.cx-reader-json-node').length<500));
  checks.push(`Large-array search browser round: ${Date.now()-start}ms (includes automation)`);
  await page.press('.cx-detail-body','Escape');await settle();
  check('Escape exits expansion before closing details',await page.evaluate(()=>!!document.querySelector('.cx-inspector')&&!document.querySelector('.cx-reader-expanded')));
  await page.focus('[aria-label="Resize content preview"]');
  const width=await page.evaluate(()=>document.querySelector('.cx-inspector').getBoundingClientRect().width);
  await page.press('[aria-label="Resize content preview"]','ArrowLeft');
  check('Keyboard panel resizing is retained',await page.evaluate(w=>document.querySelector('.cx-inspector').getBoundingClientRect().width>w,width));
  await writeFile(`${artifactDir}/checks.json`,JSON.stringify(checks,null,2));
  return checks;
}
